+fn param(records: &[cnc::Record], name: &str) -> f64 {
+    records
+        .iter()
+        .find_map(|r| match r {
+            cnc::Record::Param { name: n, value } if n == name => value.as_f64(),
+            _ => None,
+        })
+        .unwrap_or_else(|| panic!("the stream states no {name}"))
+}
